import{_ as s,C as c,o as d,c as l,j as o,a,E as t,a2 as i}from"./chunks/framework.BxGh02fV.js";const g=JSON.parse('{"title":"Piloter le travail","description":"","frontmatter":{"title":"Piloter le travail"},"headers":[],"relativePath":"agent/piloter.md","filePath":"agent/piloter.md"}'),n={name:"agent/piloter.md"};function u(p,r,f,m,h,v){const e=c("Ask");return d(),l("div",null,[r[0]||(r[0]=o("h1",{id:"piloter-le-travail",tabindex:"-1"},[a("Piloter le travail "),o("a",{class:"header-anchor",href:"#piloter-le-travail","aria-label":'Permalink to "Piloter le travail"'},"​")],-1)),r[1]||(r[1]=o("p",null,"Les épics, leurs stories et leurs tâches forment l'arbre du travail. Vous venez ici pour demander à l'agent de le créer, de le faire avancer, de le suspendre ou de le clore, sans toucher vous-même aux fichiers.",-1)),r[2]||(r[2]=o("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[a("Ce que vous demandez à l'agent "),o("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(e,{say:"Ouvre un épic « Export des données » dans la zone Données.",verb:"effortless_epic_start",family:"cycle-de-vie",args:'{"zone":"Données","title":"Export des données"}'}),t(e,{say:"Crée une story « Export CSV » dans cet épic et active-la.",verb:"effortless_story_start",family:"cycle-de-vie",args:'{"title":"Export CSV","activate":true}'}),t(e,{say:"Ajoute trois tâches à la story : le format, le bouton, les tests.",verb:"effortless_task_add",family:"cycle-de-vie",args:'{"title":"Le format"}'}),t(e,{say:"Passe la tâche TSK-02 de la story 003 de l'épic 012 en cours.",verb:"effortless_task_update",family:"cycle-de-vie",args:'{"epic_id":"012","story_id":"003","task_id":"TSK-02","status":"Doing"}'}),t(e,{say:"J'en ai assez pour aujourd'hui : mets la story en pause, motif : on attend la réponse du client.",verb:"effortless_story_pause",family:"cycle-de-vie",args:'{"reason":"On attend la réponse du client"}'}),t(e,{say:"Reprends la story 003, celle d'hier.",verb:"effortless_story_activate",family:"cycle-de-vie",args:'{"story_id":"003"}'}),t(e,{say:"Cette story est faite : clos-la, puis clos l'épic.",verb:"effortless_story_complete",family:"cycle-de-vie"}),t(e,{say:"La story 004 a été remplacée par la 006 : marque-la comme telle.",verb:"effortless_story_supersede",family:"cycle-de-vie",args:'{"story_id":"004","by":"006"}'}),t(e,{say:"Retire la story 007 : la fonctionnalité est abandonnée.",verb:"effortless_story_retire",family:"cycle-de-vie",args:'{"story_id":"007","reason":"fonctionnalité abandonnée"}'}),r[3]||(r[3]=i('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="creer-et-activer-un-epic" tabindex="-1">Créer et activer un épic <a class="header-anchor" href="#creer-et-activer-un-epic" aria-label="Permalink to &quot;Créer et activer un épic&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#epic-start"><code>effortless_epic_start</code></a> : crée l&#39;épic dans une <code>zone</code>, avec un <code>title</code> et une <code>description</code> facultative. Par défaut (<code>activate</code> à <code>true</code>), il devient l&#39;épic actif ; <code>activate: false</code> se contente de le créer.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#epic-activate"><code>effortless_epic_activate</code></a> : réactive un épic <strong>existant</strong> (<code>epic_id</code>) sans passer par une story. Il vide la story active. Rejoué, il ne change rien.</li></ol><h3 id="creer-et-activer-une-story" tabindex="-1">Créer et activer une story <a class="header-anchor" href="#creer-et-activer-une-story" aria-label="Permalink to &quot;Créer et activer une story&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-start"><code>effortless_story_start</code></a> : crée la story dans l&#39;épic actif ou dans <code>epic_id</code>. Paramètres utiles : <code>title</code>, <code>slug</code>, <code>zone</code>, <code>depends_on</code>, <code>objective</code>, <code>activate</code>. <code>kind</code> vaut <code>opale</code> (par défaut, avec cadrage) ou <code>fix</code> (correctif direct, voir <a href="/Effortless/agent/cadrer.html">Cadrer en OPALE</a>). <code>taskless_reason</code> dit pourquoi une story n&#39;aura aucune tâche (cadrage pur, jalon, décision).</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-activate"><code>effortless_story_activate</code></a> : active une story existante (<code>story_id</code>) et rouvre son épic si besoin.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-objective"><code>effortless_story_objective</code></a> : pose ou corrige l&#39;objectif de la story, en une ou deux phrases. Une chaîne vide le retire.</li></ol><h3 id="ajouter-des-taches" tabindex="-1">Ajouter des tâches <a class="header-anchor" href="#ajouter-des-taches" aria-label="Permalink to &quot;Ajouter des tâches&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#task-add"><code>effortless_task_add</code></a> : ajoute une tâche <strong>Todo</strong> à la story active (ou à <code>story_id</code>). L&#39;agent peut passer <code>description</code>, <code>phase</code>, <code>stack</code> (les normes de développement qui s&#39;y appliquent, une norme inexistante est refusée) et un classement de routage facultatif (<code>complexity</code>, <code>capability_tier</code>, <code>effort_level</code>). Le moteur renvoie l&#39;identifiant <code>TSK-NN</code>.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-items"><code>effortless_story_items</code></a> : relit les décisions, les questions et les tâches d&#39;une story.</li></ol><h3 id="faire-avancer-une-tache" tabindex="-1">Faire avancer une tâche <a class="header-anchor" href="#faire-avancer-une-tache" aria-label="Permalink to &quot;Faire avancer une tâche&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/cycle-de-vie.html#task-update"><code>effortless_task_update</code></a> change le statut d&#39;une tâche (<code>Todo</code>, <code>Doing</code>, <code>Done</code>, affichés <strong>À faire</strong>, <strong>En cours</strong>, <strong>Terminée</strong> dans l&#39;application), son titre, sa description et son résultat. Il exige au moins un champ.</p><ul><li>Passer à <strong>En cours</strong> est refusé tant que le cadrage de la story n&#39;est pas rendu, ou tant qu&#39;une tâche dont celle-ci dépend n&#39;est pas terminée.</li><li>En terminant une tâche, l&#39;agent renseigne <code>result</code> : ce qu&#39;elle a produit, constaté (fichiers, verbes, mesures). Ce texte s&#39;affiche sur la page de la tâche dans le Backlog.</li></ul><h3 id="suspendre-reprendre-reboucler" tabindex="-1">Suspendre, reprendre, reboucler <a class="header-anchor" href="#suspendre-reprendre-reboucler" aria-label="Permalink to &quot;Suspendre, reprendre, reboucler&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-pause"><code>effortless_story_pause</code></a> : suspend la story (active par défaut), date la pause et libère la story active. Le <code>reason</code> est obligatoire. Aucune tâche n&#39;est touchée.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-activate"><code>effortless_story_activate</code></a> la reprend, et l&#39;atelier se retrouve tel qu&#39;il a été laissé.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-reloop"><code>effortless_story_reloop</code></a> : renvoie la story active vers une phase OPALE antérieure (<code>target_phase</code>).</li></ol><h3 id="clore-remplacer-retirer-archiver" tabindex="-1">Clore, remplacer, retirer, archiver <a class="header-anchor" href="#clore-remplacer-retirer-archiver" aria-label="Permalink to &quot;Clore, remplacer, retirer, archiver&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-complete"><code>effortless_story_complete</code></a> : clôt la story. Elle doit avoir au moins une tâche, et toutes doivent être terminées.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-supersede"><code>effortless_story_supersede</code></a> : déclare que la story (<code>story_id</code>) est remplacée par une autre du même épic (<code>by</code>). Elle ne bloque plus la clôture de l&#39;épic et n&#39;est pas comptée comme livrée.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-retire"><code>effortless_story_retire</code></a> : retire une story <strong>non commencée</strong> qui ne sera pas faite, avec son motif (<code>reason</code>, obligatoire). Elle ne bloque plus la clôture de l&#39;épic, peut être archivée, et n&#39;est jamais comptée comme livrée ; le registre affiche « retirée : » suivi du motif. Le verbe refuse une story dont une tâche est déjà terminée : clôturez-la, ou déclarez-la remplacée.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-archive"><code>effortless_story_archive</code></a> : archive une story déjà terminée, remplacée ou retirée. Le dossier <code>.effortless/crew_contracts/&lt;épic&gt;/&lt;story&gt;/</code> de ses contrats est détruit. Rejoué, il ne change rien.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#epic-complete"><code>effortless_epic_complete</code></a> : clôt l&#39;épic (actif par défaut). Chaque story doit être terminée, remplacée ou retirée. La clôture ne résout aucune évolution du registre : celles qui restent <strong>En cours</strong> sont nommées dans la réponse (<code>evolutions_maintained</code>), et l&#39;agent vous demande ce qu&#39;on en fait (voir <a href="/Effortless/agent/evolutions.html">Registre des évolutions</a>).</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>L&#39;arbre du travail dans l&#39;écran <a href="/Effortless/guide/backlog.html">Backlog</a> : épics, stories, tâches, avec leur phase et leur état. La page d&#39;une story montre son objectif ; celle d&#39;une tâche, ce qu&#39;elle a produit.</li><li>La tâche en cours et le compteur de tâches de la story sur le <a href="/Effortless/guide/dashboard.html">Tableau de bord</a> et dans l&#39;écran <a href="/Effortless/guide/tasks.html">Tâches</a>.</li><li>Les mêmes informations rendues en Markdown dans <code>blueprints/</code> (par exemple <code>blueprints/3-Backlog.md</code>).</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Aucune story active et aucun <code>story_id</code> passé</td><td><code>pilotage:noActiveStory</code></td><td>Passer <code>epic_id</code> et <code>story_id</code>, ou activer une story.</td></tr><tr><td>Activer un épic sans le nommer</td><td><code>pilotage:epicActivateNeedsId</code></td><td>Nommer l&#39;épic ; <code>epic_start</code> en crée un neuf.</td></tr><tr><td>Activer un épic inconnu</td><td><code>pilotage:epicUnknownCannotActivate</code></td><td>Utiliser <code>epic_start</code> pour en créer un, ou <code>status</code> pour voir ceux qui existent.</td></tr><tr><td>Activer un épic déjà clos</td><td><code>pilotage:epicDoneCannotActivate</code></td><td>Activer une de ses stories : cela rouvre l&#39;épic.</td></tr><tr><td>Clore une story sans aucune tâche</td><td><code>pilotage:storyNoTask</code></td><td>Déclarer le travail avec <code>task_add</code> avant de clore.</td></tr><tr><td>Clore une story dont des tâches ne sont pas terminées</td><td><code>pilotage:storyTasksNotDone</code></td><td>Terminer les tâches.</td></tr><tr><td>Clore un épic dont des stories ne sont pas terminées</td><td><code>pilotage:epicStoriesNotDone</code></td><td>Clore chaque story nommée par le refus, ou la déclarer remplacée.</td></tr><tr><td>Suspendre une story sans motif</td><td><code>pilotage:storyPauseNeedsReason</code></td><td>Passer <code>reason</code>.</td></tr><tr><td>Suspendre une story déjà terminée</td><td><code>pilotage:storyDoneCannotPause</code></td><td>La rouvrir avec <code>story_activate</code> si le travail reprend.</td></tr><tr><td>Story inconnue</td><td><code>pilotage:storyUnknown</code></td><td>Relire les stories existantes (<code>story_items</code>, <code>project_tree</code>).</td></tr><tr><td>Remplacer une story par elle-même ou par une story d&#39;un autre épic</td><td><code>pilotage:supersederInvalid</code></td><td>Passer dans <code>by</code> une autre story du même épic.</td></tr><tr><td>Remplacer une story déjà close</td><td><code>pilotage:storyAlreadyClosed</code></td><td>Rien : une story close le reste.</td></tr><tr><td>Archiver une story qui n&#39;est pas terminée</td><td><code>pilotage:storyNotDoneCannotArchive</code></td><td>La clore d&#39;abord.</td></tr><tr><td>Mettre à jour une tâche sans aucun champ</td><td><code>pilotage:taskUpdateEmpty</code></td><td>Passer au moins <code>status</code>, <code>title</code>, <code>description</code> ou <code>result</code>.</td></tr><tr><td>Tâche à <strong>En cours</strong> pendant que le cadrage est inachevé</td><td><code>cadrage:phaseIncomplete</code></td><td>Rendre les documents manquants, ou ouvrir un correctif direct (<code>kind: &quot;fix&quot;</code>).</td></tr><tr><td>Tâche à <strong>En cours</strong> alors qu&#39;une tâche dont elle dépend n&#39;est pas terminée</td><td>refus sans code, qui nomme la tâche dépendante</td><td>Terminer d&#39;abord la tâche dépendante.</td></tr><tr><td>Norme de développement inexistante dans <code>stack</code></td><td><code>pilotage:nddUnknown</code></td><td>Passer le nom d&#39;une norme présente dans <code>.ai/ndd/</code>.</td></tr></tbody></table>',18))])}const _=s(n,[["render",u]]);export{g as __pageData,_ as default};
